import React, { useState, useEffect } from 'react';
import { LayoutDashboard, Package, BarChart3, DollarSign, Plus, CheckCircle, AlertTriangle } from 'lucide-react';

// --- MOCK DATA ---
const initialInventory = [
  { id: 1, name: 'Organic Heirloom Tomatoes', stock: 4, unit: 'lbs', price: 4.50, status: 'low' },
  { id: 2, name: 'Sweet Corn (6-pack)', stock: 32, unit: 'packs', price: 6.00, status: 'ok' },
  { id: 3, name: 'Zucchini', stock: 45, unit: 'lbs', price: 2.00, status: 'ok' },
  { id: 4, name: 'Rainbow Chard', stock: 18, unit: 'bunches', price: 3.50, status: 'ok' },
  { id: 5, name: 'Free-Range Eggs (Dozen)', stock: 8, unit: 'cartons', price: 7.00, status: 'low' },
];

const recentTransactions = [
  { id: 1, time: '2:14 PM', item: 'Misc. Veggie Box', payment: 'Card', total: 25.00 },
  { id: 2, time: '2:11 PM', item: 'Sweet Corn (6-pack)', payment: 'Cash', total: 6.00 },
  { id: 3, time: '2:05 PM', item: 'Organic Heirloom Tomatoes', payment: 'Card', total: 9.00 },
  { id: 4, time: '1:58 PM', item: 'Misc. Veggie Box', payment: 'Cash', total: 20.00 },
  { id: 5, time: '1:45 PM', item: 'Zucchini', payment: 'Card', total: 4.00 },
  { id: 6, time: '1:42 PM', item: 'Misc. Veggie Box', payment: 'Card', total: 25.00 },
];

// --- HELPER COMPONENTS ---
const NavItem = ({ icon, label, active, onClick }) => (
  <button
    onClick={onClick}
    className={`flex items-center w-full text-left px-4 py-3 text-sm font-medium rounded-lg transition-all duration-200 ${active ? 'bg-green-100 text-green-800' : 'text-slate-600 hover:bg-slate-100'}`}>
    {icon}
    <span className="ml-3">{label}</span>
  </button>
);

const StatCard = ({ title, value, change }) => (
  <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
    <p className="text-sm text-slate-500">{title}</p>
    <p className="text-2xl font-semibold text-slate-800 mt-1">{value}</p>
    {change && <p className="text-xs text-green-600 mt-1">{change}</p>}
  </div>
);

// --- MAIN PROTOTYPE COMPONENT ---
export default function FarmStandProPrototype() {
  const [currentScreen, setCurrentScreen] = useState('sales');
  const [inventory, setInventory] = useState(initialInventory);
  const [showConfirmation, setShowConfirmation] = useState(false);
  const [newProductName, setNewProductName] = useState('Standard Veggie Box');
  const [newProductPrice, setNewProductPrice] = useState('25.00');

  useEffect(() => {
    if (showConfirmation) {
      const timer = setTimeout(() => setShowConfirmation(false), 4000);
      return () => clearTimeout(timer);
    }
  }, [showConfirmation]);

  const handleAddProduct = (e) => {
    e.preventDefault();
    const newProduct = {
      id: inventory.length + 1,
      name: newProductName,
      stock: 20,
      unit: 'boxes',
      price: parseFloat(newProductPrice),
      status: 'ok',
    };
    setInventory([newProduct, ...inventory]);
    setCurrentScreen('inventory');
    setShowConfirmation(true);
  };

  const Sidebar = () => (
    <aside className="w-64 bg-slate-50 border-r border-slate-200 p-4 flex flex-col">
      <div className="flex items-center mb-8">
        <img src="/logo-placeholder.svg" alt="Logo" className="h-8 w-8 bg-green-700 rounded-lg"/>
        <h1 className="text-xl font-bold text-slate-800 ml-2">FarmStand Pro</h1>
      </div>
      <nav className="space-y-2">
        <NavItem icon={<LayoutDashboard size={20} />} label="Dashboard" active={currentScreen === 'dashboard'} onClick={() => setCurrentScreen('dashboard')} />
        <NavItem icon={<Package size={20} />} label="Inventory" active={currentScreen === 'inventory'} onClick={() => setCurrentScreen('inventory')} />
        <NavItem icon={<DollarSign size={20} />} label="Sales" active={currentScreen === 'sales'} onClick={() => setCurrentScreen('sales')} />
        <NavItem icon={<BarChart3 size={20} />} label="Reports" active={currentScreen === 'reports'} onClick={() => setCurrentScreen('reports')} />
      </nav>
      <div className="mt-auto">
        <div className="border-t border-slate-200 pt-4">
            <p className="text-sm font-semibold text-slate-700">Rodriguez Family Farms</p>
            <p className="text-xs text-slate-500">Maria Rodriguez</p>
        </div>
      </div>
    </aside>
  );

  const SalesScreen = () => (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-slate-800">Today's Sales</h2>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <StatCard title="Total Revenue" value="$742.50" change="+15% from last Saturday" />
        <StatCard title="Transactions" value="86" />
        <StatCard title="Avg. Sale Value" value="$8.63" />
      </div>
      <div className="bg-amber-50 border-l-4 border-amber-400 p-4 rounded-r-lg">
        <div className="flex">
          <div className="flex-shrink-0">
            <AlertTriangle className="h-5 w-5 text-amber-500" aria-hidden="true" />
          </div>
          <div className="ml-3">
            <h3 className="text-sm font-semibold text-amber-800">Smart Suggestion</h3>
            <div className="mt-2 text-sm text-amber-700">
              <p>You've manually entered 'Misc. Veggie Box' 12 times today. Create a standard product to speed up checkout.</p>
            </div>
            <div className="mt-4">
                <button onClick={() => setCurrentScreen('addProduct')} className="bg-amber-500 text-white font-bold py-2 px-4 rounded-lg hover:bg-amber-600 transition-all duration-200 shadow-sm">
                  Create Product
                </button>
            </div>
          </div>
        </div>
      </div>
      <div>
        <h3 className="text-lg font-semibold text-slate-700 mb-3">Recent Transactions</h3>
        <div className="bg-white border border-slate-200 rounded-lg shadow-sm">
          <ul className="divide-y divide-slate-200">
            {recentTransactions.map(tx => (
              <li key={tx.id} className={`p-4 flex justify-between items-center ${tx.item === 'Misc. Veggie Box' ? 'bg-amber-50/50' : ''}`}>
                <div>
                  <p className="font-medium text-slate-800">{tx.item}</p>
                  <p className="text-sm text-slate-500">{tx.time} &bull; {tx.payment}</p>
                </div>
                <p className="font-semibold text-slate-800">${tx.total.toFixed(2)}</p>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );

  const AddProductScreen = () => (
    <div className="space-y-6">
        <h2 className="text-2xl font-bold text-slate-800">Add New Product</h2>
        <div className="bg-white p-6 rounded-lg border border-slate-200 shadow-sm max-w-2xl">
            <form className="space-y-6" onSubmit={handleAddProduct}>
                <div>
                    <label htmlFor="productName" className="block text-sm font-medium text-slate-700">Product Name</label>
                    <input type="text" id="productName" value={newProductName} onChange={(e) => setNewProductName(e.target.value)} className="mt-1 block w-full px-3 py-2 bg-white border border-slate-300 rounded-md shadow-sm placeholder-slate-400 focus:outline-none focus:ring-green-500 focus:border-green-500" />
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label htmlFor="price" className="block text-sm font-medium text-slate-700">Price</label>
                        <div className="relative mt-1 rounded-md shadow-sm">
                            <div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3"><span className="text-gray-500 sm:text-sm">$</span></div>
                            <input type="text" id="price" value={newProductPrice} onChange={(e) => setNewProductPrice(e.target.value)} className="block w-full rounded-md border-slate-300 pl-7 pr-2 focus:border-green-500 focus:ring-green-500" />
                        </div>
                    </div>
                    <div>
                        <label htmlFor="stock" className="block text-sm font-medium text-slate-700">Initial Stock</label>
                        <input type="number" id="stock" defaultValue="20" className="mt-1 block w-full px-3 py-2 bg-white border border-slate-300 rounded-md shadow-sm placeholder-slate-400 focus:outline-none focus:ring-green-500 focus:border-green-500" />
                    </div>
                </div>
                <div>
                    <label htmlFor="category" className="block text-sm font-medium text-slate-700">Category</label>
                    <select id="category" className="mt-1 block w-full pl-3 pr-10 py-2 text-base border-slate-300 focus:outline-none focus:ring-green-500 focus:border-green-500 sm:text-sm rounded-md">
                        <option>Vegetables</option>
                        <option>Fruits</option>
                        <option>Dairy & Eggs</option>
                        <option>Pantry</option>
                    </select>
                </div>
                <div className="flex justify-end pt-4">
                    <button type="button" onClick={() => setCurrentScreen('sales')} className="bg-white py-2 px-4 border border-slate-300 rounded-md shadow-sm text-sm font-medium text-slate-700 hover:bg-slate-50 focus:outline-none">Cancel</button>
                    <button type="submit" className="ml-3 inline-flex items-center justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-green-700 hover:bg-green-800 focus:outline-none">
                        <Plus size={16} className="-ml-1 mr-2"/> Add Product to Inventory
                    </button>
                </div>
            </form>
        </div>
    </div>
  );

  const InventoryScreen = () => (
    <div className="space-y-6">
        <div className="flex justify-between items-center">
            <h2 className="text-2xl font-bold text-slate-800">Inventory</h2>
            <button onClick={() => setCurrentScreen('addProduct')} className="inline-flex items-center justify-center py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-green-700 hover:bg-green-800">
                <Plus size={16} className="-ml-1 mr-2"/> Add Product
            </button>
        </div>

        {showConfirmation && (
          <div className="bg-green-50 border-l-4 border-green-400 p-4 rounded-r-lg">
            <div className="flex">
              <div className="flex-shrink-0">
                <CheckCircle className="h-5 w-5 text-green-500" aria-hidden="true" />
              </div>
              <div className="ml-3">
                <p className="text-sm font-medium text-green-800">'Standard Veggie Box' has been successfully added to your inventory!</p>
              </div>
            </div>
          </div>
        )}

        <div className="bg-white border border-slate-200 rounded-lg shadow-sm overflow-hidden">
            <table className="min-w-full divide-y divide-slate-200">
                <thead className="bg-slate-50">
                    <tr>
                        <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Product</th>
                        <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Stock</th>
                        <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Price</th>
                    </tr>
                </thead>
                <tbody className="bg-white divide-y divide-slate-200">
                    {inventory.map(item => (
                        <tr key={item.id} className={item.name === 'Standard Veggie Box' && showConfirmation ? 'bg-green-50' : ''}>
                            <td className="px-6 py-4 whitespace-nowrap">
                                <p className="text-sm font-medium text-slate-900">{item.name}</p>
                            </td>
                            <td className="px-6 py-4 whitespace-nowrap">
                                {item.status === 'low' ? (
                                    <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-red-100 text-red-800">{item.stock} {item.unit} &bull; Low Stock</span>
                                ) : (
                                    <span className="text-sm text-slate-600">{item.stock} {item.unit}</span>
                                )}
                            </td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">${item.price.toFixed(2)}</td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </div>
    </div>
  );

  const renderScreen = () => {
    switch (currentScreen) {
      case 'sales': return <SalesScreen />;
      case 'addProduct': return <AddProductScreen />;
      case 'inventory': return <InventoryScreen />;
      default: return <SalesScreen />;
    }
  };

  return (
    <div className="flex h-screen bg-slate-100 font-sans antialiased" style={{ fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <Sidebar />
      <main className="flex-1 p-8 overflow-y-auto">
        <div className="max-w-4xl mx-auto">
          {renderScreen()}
        </div>
      </main>
    </div>
  );
}
